  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Thalidomide, the closest analogue sharing the glutarimide-isoindolinone scaffold, has absolute oral bioavailability of 80-100% in fasting healthy volunteers, directly supporting F >=20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Aminoglutethimide, another glutarimide-containing drug, shows ~100% oral bioavailability, supporting high F for this scaffold class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Nevirapine, a moderately similar heteroaromatic drug, has absolute oral bioavailability of 93%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Oxcarbazepine, an aromatic fused-ring drug, has >95% oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tivantinib, a fused heteroaromatic drug, has oral bioavailability of at least 20%, meeting the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "THU, a small cyclic urea, has only 10-14% oral bioavailability, but its structure is very dissimilar to the query and carries low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest and most transferable evidence, thalidomide, shows high absolute oral bioavailability (80-100%) in fasting humans, and the query shares the same glutarimide-isoindolinone scaffold. Additional structurally diverse drugs with high F support the positive direction; the only sub-20% example is very dissimilar. Therefore F >=20% is supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query or a very close analogue such as lenalidomide was retrieved.",
    "The closest analogue thalidomide has only moderate Morgan similarity (0.5455) and differs by an amino group and lactam vs imide functionality.",
    "Fasted-state absolute F data for the query itself are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

